-- Teknik-O Kombi ham veri importu
-- Kaynak: Teknik-O_Kombi_Staging_Import_4457_Resolved.xlsx
-- Vaillant mevcut 1.422 kayıt korunur; bu migration yalnız 4.457 yeni kaydı ekler.
-- UI / diğer tablolar / verified adaylar / sorular / fiyatlar bu migration ile değiştirilmez.

BEGIN;

-- Güvenlik ön koşulları: canlı başlangıç beklediğimiz durumda değilse hiçbir şey yazma.
DO $$
DECLARE
  v_total bigint;
  v_vaillant bigint;
  v_non_vaillant bigint;
BEGIN
  SELECT count(*) INTO v_total FROM public.official_error_codes_raw;
  SELECT count(*) INTO v_vaillant FROM public.official_error_codes_raw WHERE lower(brand) = lower('Vaillant');
  SELECT count(*) INTO v_non_vaillant FROM public.official_error_codes_raw WHERE lower(brand) <> lower('Vaillant');

  IF v_total <> 1422 OR v_vaillant <> 1422 OR v_non_vaillant <> 0 THEN
    RAISE EXCEPTION
      'Import durduruldu. Beklenen başlangıç total=1422, Vaillant=1422, non-Vaillant=0; mevcut total=%, Vaillant=%, non-Vaillant=%',
      v_total, v_vaillant, v_non_vaillant;
  END IF;
END $$;

