) AS v(brand, official_model, error_code, official_description, official_action, source_url, import_batch)
WHERE NOT EXISTS (
  SELECT 1
  FROM public.official_error_codes_raw e
  WHERE lower(trim(e.brand)) = lower(trim(v.brand))
    AND lower(trim(e.official_model)) = lower(trim(v.official_model))
    AND lower(trim(e.error_code)) = lower(trim(v.error_code))
);

-- Sonuç doğrulaması: beklenen toplam ve marka bazlı sayılar.
DO $$
DECLARE
  v_total bigint;
  v_imported bigint;
  v_dup_groups bigint;
BEGIN
  SELECT count(*) INTO v_total FROM public.official_error_codes_raw;
  SELECT count(*) INTO v_imported
  FROM public.official_error_codes_raw
  WHERE import_batch = 'kombi_excel_staging_2026-09-26';

  SELECT count(*) INTO v_dup_groups
  FROM (
    SELECT lower(trim(brand)), lower(trim(official_model)), lower(trim(error_code))
    FROM public.official_error_codes_raw
    GROUP BY 1,2,3
    HAVING count(*) > 1
  ) d;

  IF v_total <> 5879 THEN
    RAISE EXCEPTION 'Import sonrası toplam beklenenden farklı. Beklenen=5879, mevcut=%', v_total;
  END IF;

  IF v_imported <> 4457 THEN
    RAISE EXCEPTION 'Bu import_batch için beklenen kayıt=4457, mevcut=%', v_imported;
  END IF;

  IF v_dup_groups <> 0 THEN
    RAISE EXCEPTION 'Import sonrası brand+model+error_code duplicate grubu bulundu: %', v_dup_groups;
  END IF;
END $$;

DO $$
DECLARE v_count bigint;
BEGIN
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'Alpha';
  IF v_count <> 38 THEN RAISE EXCEPTION 'Alpha kayıt sayısı beklenen 38, mevcut=%', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'Ariston';
  IF v_count <> 760 THEN RAISE EXCEPTION 'Ariston kayıt sayısı beklenen 760, mevcut=%', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'Baymak';
  IF v_count <> 183 THEN RAISE EXCEPTION 'Baymak kayıt sayısı beklenen 183, mevcut=%', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'Bosch';
  IF v_count <> 126 THEN RAISE EXCEPTION 'Bosch kayıt sayısı beklenen 126, mevcut=%', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'Buderus';
  IF v_count <> 376 THEN RAISE EXCEPTION 'Buderus kayıt sayısı beklenen 376, mevcut=%', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'DemirDöküm';
  IF v_count <> 964 THEN RAISE EXCEPTION 'DemirDöküm kayıt sayısı beklenen 964, mevcut=%', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'E.C.A.';
  IF v_count <> 322 THEN RAISE EXCEPTION 'E.C.A. kayıt sayısı beklenen 322, mevcut=%', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'Immergas';
  IF v_count <> 580 THEN RAISE EXCEPTION 'Immergas kayıt sayısı beklenen 580, mevcut=%', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'Lambert';
  IF v_count <> 256 THEN RAISE EXCEPTION 'Lambert kayıt sayısı beklenen 256, mevcut=%', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'Viessmann';
  IF v_count <> 444 THEN RAISE EXCEPTION 'Viessmann kayıt sayısı beklenen 444, mevcut=%', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'Warmhaus';
  IF v_count <> 408 THEN RAISE EXCEPTION 'Warmhaus kayıt sayısı beklenen 408, mevcut=%', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.official_error_codes_raw WHERE brand = 'Vaillant';
  IF v_count <> 1422 THEN RAISE EXCEPTION 'Vaillant kayıt sayısı değişti. Beklenen 1422, mevcut=%', v_count; END IF;
END $$;

COMMIT;
